#include "feature_mcp_control.hpp"
#include "feature_bridge.hpp"
#include <fstream>
#include <iostream>
#include <set>
using namespace scratcher;
static void check(bool ok,const char*message){if(!ok)throw std::runtime_error(message);}
static bool done(const Json&job){auto state=job.value("status",std::string());return state=="completed"||state=="failed"||state=="cancelled";}
int main(){try{
 auto dir=executableDir()/"mcp-control-fixtures";std::filesystem::create_directories(dir);auto raw=dir/"input.bin";{std::ofstream out(raw,std::ios::binary);std::vector<char> bytes(64,char(0x90));bytes[0]=char(0xb8);bytes[1]=42;bytes[2]=bytes[3]=bytes[4]=0;bytes[5]=char(0xc3);out.write(bytes.data(),bytes.size());}
 Engine engine;Tools tools(engine);auto backend=createAutomationBackend(engine,tools);tools.setBackend(backend.get());
 std::set<std::string> unique;for(auto& tool:tools.list())check(unique.insert(tool.at("name").get<std::string>()).second,"tool names unique");check(tools.list().size()==tools.localList().size()+17,"analysis tools plus 17 desktop controls");check(tools.call("get_session",Json::object())["mode"]=="isolated","default independent session");tools.call("open_binary",{{"path",pathText(raw)}});check(tools.call("get_workspace_state",Json::object())["binary"]["size"]==64,"serialized independent snapshot");
 auto job=tools.call("submit_job",{{"tool","decompile"},{"arguments",{{"address","0x1000"}}}});check(job["job_id"].is_string(),"job ID string");auto finished=tools.call("await_job",{{"job_id",job["job_id"]},{"timeout_ms",30000}});check(finished["status"]=="completed"&&finished["result"]["code"].is_string(),"async analysis result");check(tools.call("get_job",{{"job_id",job["job_id"]}})["result"]==finished["result"],"job result can be read repeatedly");
 auto dry=tools.call("batch_tools",{{"operations",Json::array({{{"tool","set_comment"},{"arguments",{{"address","0x1000"},{"text","dry"}}}}})},{"dry_run",true}});check(dry["dry_run"]==true&&tools.call("list_annotations",Json::object())["count"]==0,"schema-only dryrun preserves notes");
 auto batch=tools.call("batch_tools",{{"operations",Json::array({{{"tool","set_comment"},{"arguments",{{"address","0x1000"},{"text","MCP note"}}}},{{"tool","set_bookmark"},{"arguments",{{"address","0x1000"},{"name","Start"}}}},{{"tool","rename_function"},{"arguments",{{"address","0x1000"},{"name","answer"}}}}})}});check(batch["attempted"]==3&&batch["failed"]==false,"batch edits execute");check(tools.call("decompile",{{"address","0x1000"}})["code"].get<std::string>().find("answer")!=std::string::npos,"batch rename affects code");
 bool rejected=false;try{tools.call("batch_tools",{{"operations",Json::array({{{"tool","set_comment"},{"arguments",{{"address","0x1000"},{"text","should not apply"}}}},{{"tool","cancel_job"},{"arguments",{{"job_id","1"}}}}})}});}catch(...){rejected=true;}check(rejected&&tools.call("list_annotations",Json::object())["annotations"][0]["comment"]=="MCP note","entire batch schemas validate before editing");
 rejected=false;try{tools.call("submit_job",{{"tool","submit_job"}});}catch(...){rejected=true;}check(rejected,"nested job controls rejected");
 auto resource=backend->resourceRead("scratcher://workspace");check(Json::parse(resource["contents"][0]["text"].get<std::string>())["binary"]["size"]==64,"workspace resource");check(backend->resourcesList()["resources"].size()==6,"six workspace resources");check(backend->promptsList()["prompts"].size()==2,"two analysis prompts");check(backend->promptGet("trace_function",{{"address","0x1000"}})["messages"].size()==1,"trace prompt resolves");
 rejected=false;try{tools.call("navigate_to",{{"address","0x1000"}});}catch(...){rejected=true;}check(rejected,"live controls require explicit attachment");
 BridgeServer server(executableDir()/"sessions",[](const Json&request){return Json{{"remote",true},{"request",request}};});auto endpoint=server.endpoint();auto attached=tools.call("attach_session",{{"session_id",endpoint["id"]}});check(attached["mode"]=="desktop","attaches by discovered identity");check(tools.call("get_binary_info",Json::object())["remote"]==true,"existing analysis tools route to desktop");check(tools.call("set_active_view",{{"view","Graph"}})["request"]["name"]=="set_active_view","desktop controls route through bridge");check(tools.call("get_session",Json::object())["session"]["id"]==endpoint["id"],"attached session retained");
 tools.call("detach_session",Json::object());check(tools.call("get_binary_info",Json::object())["size"]==64,"detach preserves independent workspace");server.stop();
 std::cout<<"PASS: live routing, batch edits, async jobs, resources, prompts and independent workspace\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
